static int compare(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int primes[] = {2, 3, 5, 7, 11, 13};
    int key = 7;
    int *hit = bsearch(&key, primes, 6, sizeof primes[0], compare);
